mapper.select:
SELECT DISTINCT c.*
FROM conversations c
INNER JOIN conversation_members cm ON c.id = cm.conversation_id
WHERE cm.user_id = #{userId}
AND c.deleted_at IS NULL

    AND c.id > #{cursorId}

ORDER BY c.id ASC
LIMIT #{pageSize}

SELECT c.id, c.public_id AS publicId, c.type, CASE WHEN c.type = 'PRIVATE' THEN COALESCE( (SELECT CASE WHEN u.nickname IS NOT NULL AND u.nickname != '' AND u.nickname NOT LIKE 'AIHub\_%' ESCAPE '\' THEN u.nickname ELSE u.username END FROM conversation_members peer JOIN users u ON u.id = peer.user_id AND u.deleted_at IS NULL WHERE peer.conversation_id = c.id AND peer.user_id != #{userId} ORDER BY peer.id LIMIT 1), '已注销用户') ELSE c.name END AS name, c.latest_message_id AS latestMessageId, m.public_id AS latestMessagePublicId, CASE WHEN NULLIF(BTRIM(m.content), '') IS NOT NULL THEN m.content WHEN m.public_id IS NULL THEN NULL WHEN m.media_type = 'FILE' THEN '[文件]' || CASE WHEN NULLIF(BTRIM(cf.original_filename), '') IS NOT NULL THEN ' ' || cf.original_filename ELSE '' END WHEN m.media_type = 'IMAGE' THEN '[图片]' WHEN m.media_type = 'VOICE' THEN '[语音]' WHEN m.media_type = 'VIDEO' THEN '[视频]' ELSE '[消息]' END AS latestMessageContent, m.created_at AS latestMessageCreatedAt, (SELECT COUNT(*) FROM messages m2 WHERE m2.conversation_id = c.id AND m2.deleted_at IS NULL AND m2.sender_id != #{userId} AND m2.id > coalesce(cm.last_read_message_id, 0) ) AS unreadCount FROM conversations c INNER JOIN conversation_members cm ON c.id = cm.conversation_id LEFT JOIN messages m ON m.id = c.latest_message_id LEFT JOIN chat_files cf ON cf.id = m.file_id AND cf.deleted_at IS NULL WHERE cm.user_id = #{userId} AND c.deleted_at IS NULL
AND COALESCE(c.latest_message_id, c.id) < #{cursorId}
ORDER BY COALESCE(c.latest_message_id, c.id) DESC LIMIT #{pageSize}

SELECT c.id, c.public_id, c.type, c.name, c.announcement, c.latest_message_id, c.created_at, c.deleted_at, (SELECT COUNT(*) FROM conversation_members actual WHERE actual.conversation_id = c.id) AS member_count FROM conversations c INNER JOIN conversation_members cm ON c.id = cm.conversation_id WHERE cm.user_id = #{userId} AND c.type = 'GROUP' AND c.deleted_at IS NULL
AND c.id > #{cursor}
AND c.name LIKE concat('%', #{keyword}, '%')
ORDER BY c.id ASC LIMIT #{limit}
